"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion, useScroll } from "motion/react";
import { useId, useRef, useState } from "react";
import { ARTEMIS_SPRING_LAYOUT } from "../../../lib/ease";
import { ALL_ITEMS, FILTERS, filterCount, matchesFilter, PERIODS, type RoadmapFilter, type RoadmapItem, STATUS_LABEL, } from "./01-timeline/data";
import { type FilterTabItem, FilterTabs } from "./01-timeline/filter-tabs";
import { ItemDialog } from "./01-timeline/item-dialog";
import { StatusIcon } from "./01-timeline/status-icon";
import { VoteButton } from "./01-timeline/vote-button";
const TITLE_BUTTON_CLASS = "art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-ring art:focus-visible:ring-offset-background art:inline-block art:h-auto art:p-0 art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:text-left art:font-medium art:text-xl art:after:absolute art:after:inset-0 art:after:content-[''] art:focus-visible:ring-0 art:focus-visible:ring-offset-0 art:rounded-full";
function RoadmapCard({ item, voted, onToggleVote, onOpen, }: {
    item: RoadmapItem;
    voted: boolean;
    onToggleVote: () => void;
    onOpen: () => void;
}) {
    const reduce = useReducedMotion();
    return (<motion.li layout={!reduce} className="art:relative art:pl-12" initial={false} animate={{ opacity: 1, filter: "blur(0px)", y: 0 }}>
      <StatusIcon item={item} className="art:absolute art:top-5 art:left-0"/>
      <article className="art:relative art:rounded-2xl art:border art:border-border art:bg-background art:p-5 art:transition-colors art:duration-200 art:hover:border-foreground/25 art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-foreground">
        <div className="art:flex art:items-start art:justify-between art:gap-4 art:@max-[340px]/artemis:flex-col">
          <div className="art:min-w-0">
            <p className="art:text-muted-foreground art:text-xs">
              {item.area} · {STATUS_LABEL[item.status]}
              {item.progress !== undefined ? ` \u00B7 ${item.progress}%` : null}
            </p>
            <h4 className="art:mt-2 art:font-medium art:text-xl">
              <button type="button" className={TITLE_BUTTON_CLASS} aria-haspopup="dialog" onClick={onOpen}>
                {item.title}
              </button>
            </h4>
            <p className="art:mt-2 art:max-w-lg art:text-muted-foreground art:text-sm art:leading-6">{item.description}</p>
          </div>
          <VoteButton title={item.title} votes={item.votes} voted={voted} onToggle={onToggleVote}/>
        </div>
      </article>
    </motion.li>);
}
export default function RoadmapTimeline() {
    const reduce = useReducedMotion();
    const titleId = useId();
    const [filter, setFilter] = useState<RoadmapFilter>("all");
    const [votes, setVotes] = useState<Record<string, boolean>>({});
    const [openId, setOpenId] = useState<string | null>(null);
    const timelineRef = useRef<HTMLDivElement>(null);
    const { scrollYProgress } = useScroll({ target: timelineRef, offset: ["start 0.75", "end 0.6"] });
    const toggleVote = (itemId: string) => setVotes((prev) => ({ ...prev, [itemId]: !prev[itemId] }));
    const openItem = ALL_ITEMS.find((item) => item.id === openId) ?? null;
    const periods = PERIODS.map((period) => ({
        ...period,
        items: period.items.filter((item) => matchesFilter(item, filter)),
    })).filter((period) => period.items.length > 0);
    const tabs = FILTERS.map(({ value, label }): FilterTabItem<RoadmapFilter> => ({
        value,
        label: (<>
        {label}
        <span className="art:hidden art:font-mono art:text-xs art:tabular-nums art:opacity-60 art:@min-[640px]/artemis:inline">{filterCount(value)}</span>
      </>),
    }));
    return (<section className="art:w-full art:bg-background art:px-4 art:py-16 art:font-sans art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24" aria-labelledby={titleId}>
      <div className="art:mx-auto art:w-full art:max-w-5xl">
        <div className="art:flex art:flex-col art:gap-8 art:@min-[1024px]/artemis:flex-row art:@min-[1024px]/artemis:items-end art:@min-[1024px]/artemis:justify-between">
          <div className="art:max-w-xl">
            <p className="art:font-mono art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">Roadmap</p>
            <h2 id={titleId} className="art:mt-4 art:text-balance art:font-medium art:text-4xl art:tracking-tight">
              What we are building, and what comes next.
            </h2>
            <p className="art:mt-4 art:text-pretty art:text-muted-foreground art:leading-7">
              Updated every two weeks. Vote for the work that matters to your team and open any item to see what is
              included.
            </p>
          </div>
          <div className="art:overflow-x-auto">
            <FilterTabs items={tabs} value={filter} onValueChange={setFilter} ariaLabel="Filter roadmap"/>
          </div>
        </div>
        <div ref={timelineRef} className="art:relative art:mt-14">
          <div aria-hidden="true" className="art:absolute art:top-4 art:bottom-4 art:left-4 art:w-px art:bg-border art:@min-[1024px]/artemis:left-[calc(10rem+2.5rem+1rem)]">
            <motion.div className="art:h-full art:w-full art:origin-top art:bg-foreground/60" style={{ scaleY: scrollYProgress }}/>
          </div>
          <AnimatePresence initial={false} mode="popLayout">
            {periods.map((period) => (<motion.section key={period.id} layout={!reduce} aria-labelledby={`${titleId}-period-${period.id}`} className="art:grid art:grid-cols-[minmax(0,1fr)] art:gap-4 art:pb-12 art:last:pb-0 art:@min-[1024px]/artemis:grid-cols-[10rem_minmax(0,1fr)] art:@min-[1024px]/artemis:gap-10" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={reduce ? undefined : { opacity: 0 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}>
                <div className="art:pl-12 art:@min-[1024px]/artemis:sticky art:@min-[1024px]/artemis:top-24 art:@min-[1024px]/artemis:self-start art:@min-[1024px]/artemis:pt-4 art:@min-[1024px]/artemis:pl-0">
                  <h3 id={`${titleId}-period-${period.id}`} className="art:font-medium art:text-xl">
                    {period.label}
                  </h3>
                  <p className="art:mt-1 art:font-mono art:text-muted-foreground art:text-xs">{period.range}</p>
                </div>
                <ul className="art:space-y-3">
                  {period.items.map((item) => (<RoadmapCard key={item.id} item={item} voted={Boolean(votes[item.id])} onToggleVote={() => toggleVote(item.id)} onOpen={() => setOpenId(item.id)}/>))}
                </ul>
              </motion.section>))}
          </AnimatePresence>
        </div>
      </div>
      <ItemDialog item={openItem} voted={openItem ? Boolean(votes[openItem.id]) : false} onToggleVote={() => {
            if (openItem)
                toggleVote(openItem.id);
        }} onClose={() => setOpenId(null)}/>
    </section>);
}

// @zeus-internal
export type RoadmapStatus = "shipped" | "in-progress" | "planned";
export type RoadmapFilter = "all" | RoadmapStatus;
export type RoadmapItem = {
    id: string;
    title: string;
    area: string;
    status: RoadmapStatus;
    progress?: number;
    votes: number;
    description: string;
    included: readonly string[];
};
export type RoadmapPeriod = {
    id: string;
    label: string;
    range: string;
    items: readonly RoadmapItem[];
};
export const STATUS_LABEL: Record<RoadmapStatus, string> = {
    shipped: "Shipped",
    "in-progress": "In progress",
    planned: "Planned",
};
export const FILTERS: readonly {
    value: RoadmapFilter;
    label: string;
}[] = [
    { value: "all", label: "All" },
    { value: "shipped", label: "Shipped" },
    { value: "in-progress", label: "In progress" },
    { value: "planned", label: "Planned" },
];
export const PERIODS: readonly RoadmapPeriod[] = [
    {
        id: "q3",
        label: "Shipped",
        range: "Jul \u2013 Sep 2026",
        items: [
            {
                id: "shared-spaces",
                title: "Shared spaces",
                area: "Collaboration",
                status: "shipped",
                votes: 412,
                description: "Group projects by team and invite partners into a single space.",
                included: ["Space-level members and roles", "Partner access without a paid seat", "Pinned projects for each space"],
            },
            {
                id: "offline-editing",
                title: "Offline editing",
                area: "Apps",
                status: "shipped",
                votes: 286,
                description: "Keep writing on a flight and sync changes when you reconnect.",
                included: ["Local drafts on desktop and mobile", "Conflict review when edits overlap", "Sync status in the sidebar"],
            },
        ],
    },
    {
        id: "q4",
        label: "Now",
        range: "Oct \u2013 Dec 2026",
        items: [
            {
                id: "calendar-sync",
                title: "Two-way calendar sync",
                area: "Integrations",
                status: "in-progress",
                progress: 68,
                votes: 538,
                description: "See due dates next to meetings and move them from either side.",
                included: ["Connected calendars", "Drag to reschedule from the calendar", "Per-project sync settings"],
            },
            {
                id: "field-permissions",
                title: "Field-level permissions",
                area: "Security",
                status: "in-progress",
                progress: 34,
                votes: 197,
                description: "Choose who can view or edit sensitive fields on any record.",
                included: ["Hidden and read-only fields", "Permission presets for common roles", "Audit entries for every change"],
            },
        ],
    },
    {
        id: "q1",
        label: "Next",
        range: "Jan \u2013 Mar 2027",
        items: [
            {
                id: "public-api-v2",
                title: "Public API v2",
                area: "Developers",
                status: "planned",
                votes: 344,
                description: "Faster endpoints, webhooks for every event, and typed SDKs.",
                included: ["Webhooks with retries", "TypeScript and Python SDKs", "Usage dashboard for API keys"],
            },
            {
                id: "widgets",
                title: "Home screen widgets",
                area: "Apps",
                status: "planned",
                votes: 159,
                description: "Check today\u2019s work and add quick notes without opening the app.",
                included: ["Today and inbox widgets", "Quick capture from the lock screen", "Light and dark styles"],
            },
        ],
    },
    {
        id: "later",
        label: "Later",
        range: "Exploring",
        items: [
            {
                id: "formula-fields",
                title: "Formula fields",
                area: "Data",
                status: "planned",
                votes: 121,
                description: "Calculate totals, dates, and scores from the fields you already track.",
                included: ["Arithmetic and date functions", "References across linked records", "Live previews while editing"],
            },
        ],
    },
];
export const ALL_ITEMS: readonly RoadmapItem[] = PERIODS.flatMap((period) => period.items);
export function matchesFilter(item: RoadmapItem, filter: RoadmapFilter): boolean {
    return filter === "all" || item.status === filter;
}
export function filterCount(filter: RoadmapFilter): number {
    return ALL_ITEMS.filter((item) => matchesFilter(item, filter)).length;
}

// @zeus-internal
import type { ReactNode } from "react";
import { ArtemisSegmentedTabs } from "../../../../foundations/segmented-tabs";
export type FilterTabItem<T extends string> = {
    value: T;
    label: ReactNode;
};
export function FilterTabs<T extends string>({ items, value, onValueChange, ariaLabel }: {
    items: FilterTabItem<T>[];
    value: T;
    onValueChange: (value: T) => void;
    ariaLabel?: string;
}) { return <ArtemisSegmentedTabs items={items} value={value} onValueChange={next => onValueChange(next as T)} ariaLabel={ariaLabel} layout="position" listClassName="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:min-w-max" buttonClassName="art:rounded-full art:gap-2"/>; }

"use client";
// @zeus-internal
import { Description, Dialog, DialogBackdrop, DialogPanel, DialogTitle } from "../../../../lib/headless";
import { Check, X } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ArtemisButton } from "../../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../../lib/ease";
import { type RoadmapItem, STATUS_LABEL } from "./data";
import { StatusIcon } from "./status-icon";
import { VoteButton } from "./vote-button";
const EXIT = { duration: 0.15, ease: ARTEMIS_EASE_OUT } as const;
function ItemDetails({ item, voted, onToggleVote, onClose, }: {
    item: RoadmapItem;
    voted: boolean;
    onToggleVote: () => void;
    onClose: () => void;
}) {
    const reduce = useReducedMotion();
    return (<div>
      <header className="art:flex art:items-start art:gap-3 art:border-border art:border-b art:px-6 art:py-5">
        <StatusIcon item={item} className="art:mt-0.5 art:shrink-0"/>
        <div className="art:min-w-0 art:flex-1">
          <p className="art:text-muted-foreground art:text-xs">
            {item.area} · {STATUS_LABEL[item.status]}
          </p>
          <DialogTitle as="h2" className="art:mt-1 art:font-medium art:text-xl">
            {item.title}
          </DialogTitle>
        </div>
        <ArtemisButton variant="ghost" size="icon" className="art:size-9" aria-label="Close details" data-autofocus onClick={onClose}>
          <X className="art:size-4" aria-hidden="true"/>
        </ArtemisButton>
      </header>
      <div className="art:space-y-6 art:px-6 art:py-6">
        <Description className="art:text-muted-foreground art:text-sm art:leading-6">{item.description}</Description>
        {item.status === "in-progress" && item.progress !== undefined ? (<div>
            <div className="art:flex art:items-center art:justify-between art:text-xs">
              <span className="art:text-muted-foreground">Progress</span>
              <span className="art:font-mono art:tabular-nums">{item.progress}%</span>
            </div>
            <div className="art:mt-2 art:h-1.5 art:overflow-hidden art:rounded-full art:bg-muted">
              <motion.div className="art:h-full art:origin-left art:rounded-full art:bg-foreground" initial={reduce ? false : { scaleX: 0 }} animate={{ scaleX: item.progress / 100 }} transition={reduce ? { duration: 0 } : { duration: 0.9, delay: 0.15, ease: ARTEMIS_EASE_OUT }}/>
            </div>
          </div>) : null}
        <div>
          <p className="art:font-mono art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">What is included</p>
          <ul className="art:mt-3 art:space-y-3">
            {item.included.map((entry, index) => (<motion.li key={entry} className="art:flex art:items-start art:gap-3 art:text-sm art:leading-6" initial={reduce ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: 0.12 + index * 0.06 }}>
                <span className="art:mt-0.5 art:grid art:size-5 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted">
                  <Check className="art:size-3" aria-hidden="true"/>
                </span>
                {entry}
              </motion.li>))}
          </ul>
        </div>
      </div>
      <footer className="art:flex art:items-center art:justify-between art:gap-3 art:border-border art:border-t art:px-6 art:py-4">
        <p className="art:text-muted-foreground art:text-sm">{voted ? "Thanks \u2014 your vote is in." : "Want this sooner?"}</p>
        <VoteButton title={item.title} votes={item.votes} voted={voted} onToggle={onToggleVote}/>
      </footer>
    </div>);
}
export function ItemDialog({ item, voted, onToggleVote, onClose, }: {
    item: RoadmapItem | null;
    voted: boolean;
    onToggleVote: () => void;
    onClose: () => void;
}) {
    const reduce = useReducedMotion();
    return (<AnimatePresence>
      {item ? (<Dialog static open onClose={onClose} className="art:relative art:z-[100]">
          <DialogBackdrop as={motion.div} className="art:fixed art:inset-0 art:bg-foreground/15 art:backdrop-blur-sm" aria-hidden="true" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1, transition: reduce ? { duration: 0 } : { duration: 0.2, ease: ARTEMIS_EASE_OUT } }} exit={reduce ? undefined : { opacity: 0, transition: EXIT }}/>
          <div className="art:fixed art:inset-0 art:z-[101] art:w-screen art:overflow-x-hidden art:overflow-y-auto art:overscroll-contain art:p-3 art:@min-[640px]/artemis:p-6">
            <div className="art:flex art:min-h-full art:items-center art:justify-center">
              <DialogPanel as={motion.div} className="art:max-h-[calc(100dvh-2rem)] art:w-full art:overflow-y-auto art:border art:border-border art:bg-background art:text-foreground art:will-change-transform art:max-w-lg art:rounded-3xl" initial={reduce ? false : { opacity: 0, y: 8, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1, transition: reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL }} exit={reduce ? undefined : { opacity: 0, y: 6, scale: 0.96, transition: EXIT }}>
                <ItemDetails item={item} voted={voted} onToggleVote={onToggleVote} onClose={onClose}/>
              </DialogPanel>
            </div>
          </div>
        </Dialog>) : null}
    </AnimatePresence>);
}

"use client";
// @zeus-internal
import { Check } from "lucide-react";
import { motion } from "motion/react";
import { artemisCx } from "../../../../lib/utils";
import type { RoadmapItem } from "./data";
const RADIUS = 13;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;
function ProgressRing({ progress }: {
    progress: number;
}) {
    return (<motion.svg viewBox="0 0 32 32" className="art:size-8 art:-rotate-90" aria-hidden="true" initial="hidden" whileInView="visible" viewport={{ once: true, amount: 0.05 }}>
      <circle cx="16" cy="16" r={RADIUS} fill="none" strokeWidth="2" className="art:stroke-border"/>
      <motion.circle cx="16" cy="16" r={RADIUS} fill="none" strokeWidth="2" strokeLinecap="round" strokeDasharray={CIRCUMFERENCE} className="art:stroke-foreground" variants={{ visible: { strokeDashoffset: CIRCUMFERENCE * (1 - progress / 100) } }}/>
    </motion.svg>);
}
export function StatusIcon({ item, className }: {
    item: RoadmapItem;
    className: string;
}) {
    if (item.status === "shipped") {
        return (<span aria-hidden="true" className={artemisCx("art:grid art:size-8 art:place-items-center art:rounded-full art:bg-background", className)}>
        <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:bg-muted">
          <Check className="art:size-3.5" aria-hidden="true"/>
        </span>
      </span>);
    }
    if (item.status === "in-progress") {
        return (<span aria-hidden="true" className={artemisCx("art:grid art:size-8 art:place-items-center art:rounded-full art:bg-background", className)}>
        <ProgressRing progress={item.progress ?? 0}/>
      </span>);
    }
    return (<span aria-hidden="true" className={artemisCx("art:grid art:size-8 art:place-items-center art:rounded-full art:bg-background art:border art:border-border art:border-dashed", className)}>
      <span className="art:size-1.5 art:rounded-full art:bg-muted-foreground"/>
    </span>);
}

"use client";
// @zeus-internal
import { ChevronUp } from "lucide-react";
import { ArtemisButton } from "../../../../foundations/button";
import { ArtemisDigitSwap } from "../../../../foundations/digit-swap";
export function VoteButton({ title, votes, voted, onToggle }: {
    title: string;
    votes: number;
    voted: boolean;
    onToggle: () => void;
}) {
    const count = votes + (voted ? 1 : 0);
    return (<ArtemisButton variant={voted ? "primary" : "tertiary"} size="sm" className="art:relative art:z-10 art:h-8 art:gap-1.5 art:px-3" aria-pressed={voted} aria-label={`${voted ? "Remove vote for" : "Vote for"} ${title}, ${count} votes`} onClick={onToggle}>
      <ChevronUp className="art:size-3.5" aria-hidden="true"/>
      <ArtemisDigitSwap value={count} direction={voted ? "up" : "down"} className="art:font-mono art:tabular-nums"/>
    </ArtemisButton>);
}
